34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "membership_points")
85	    private Integer membershipPoints;
86	
87	    @Column(name = "membership_level")
88	    private Integer membershipLevel;
89	
90	    @Column(name = "bulk_signup_warning")
91	    private Boolean bulkSignupWarning;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "deleted", nullable = false)
100	    private boolean deleted;
101	
102	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
103	    private Set<Pet> pets;
104	
105	    public String getTitle() {
106	        return this.title;
107	    }
108	
109	    public void setTitle(String title) {
110	        this.title = title;
111	    }
112	
113	    /**
114	     * The owner's salutation, derived on read from the owner's {@link #title} and last
115	     * name: {@code "<title> <lastName>"} when a title has been supplied, or just the last
116	     * name when it has not.
117	     */
118	    @Transient
119	    public String getSalutation() {
120	        if (this.title == null || this.title.isBlank()) {
121	            return getLastName();
122	        }
123	        return this.title + " " + getLastName();
124	    }
125	
126	    public String getAddress() {
127	        return this.address;
128	    }
129	
130	    public void setAddress(String address) {
131	        this.address = address;
132	    }
133	
134	    /**
135	     * The first line of the owner's structured address, when supplied. Preferred over the
136	     * flat {@link #getAddress() address} and used to compose it; {@code null} for owners
137	     * created from the flat address form.
138	     */
139	    public String getAddressLine1() {
140	        return this.addressLine1;
141	    }
142	
143	    public void setAddressLine1(String addressLine1) {
144	        this.addressLine1 = addressLine1;
145	    }
146	
147	    /**
148	     * The optional second line of the owner's structured address; {@code null} when absent.
149	     * When present it is appended to {@link #getAddressLine1() addressLine1} to compose the
150	     * {@link #getAddress() address}.
151	     */
152	    public String getAddressLine2() {
153	        return this.addressLine2;
154	    }
155	
156	    public void setAddressLine2(String addressLine2) {
157	        this.addressLine2 = addressLine2;
158	    }
159	
160	    public String getCity() {
161	        return this.city;
162	    }
163	
164	    public void setCity(String city) {
165	        this.city = city;
166	    }
167	
168	    public String getTelephone() {
169	        return this.telephone;
170	    }
171	
172	    public void setTelephone(String telephone) {
173	        this.telephone = telephone;
174	    }
175	
176	    /**
177	     * The owner's stored E.164 {@link #telephone} formatted for humans: the country code, a
178	     * space, then the national digits grouped in threes, e.g. {@code "+61 412 345 678"}.
179	     * Derived on read; {@code null} until a telephone has been set.
180	     */
181	    @Transient
182	    public String getTelephoneDisplay() {
183	        return TelephoneDisplay.format(this.telephone);
184	    }
185	
186	    public String getEmail() {
187	        return this.email;
188	    }
189	
190	    public void setEmail(String email) {
191	        this.email = email;
192	    }
193	
194	    public String getPostcode() {
195	        return this.postcode;
196	    }
197	
198	    public void setPostcode(String postcode) {
199	        this.postcode = postcode;
200	    }
201	
202	    public LocalDate getRegistrationDate() {
203	        return this.registrationDate;
204	    }
205	
206	    public void setRegistrationDate(LocalDate registrationDate) {
207	        this.registrationDate = registrationDate;
208	    }
209	
210	    public LocalDate getBirthDate() {
211	        return this.birthDate;
212	    }
213	
214	    public void setBirthDate(LocalDate birthDate) {
215	        this.birthDate = birthDate;
216	    }
217	
218	    /**
219	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
220	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
221	     * registration date have been supplied.
222	     */
223	    @Transient
224	    public String getAgeBand() {
225	        if (this.birthDate == null || this.registrationDate == null) {
226	            return null;
227	        }
228	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
229	    }
230	
231	    public String getCustomerCode() {
232	        return this.customerCode;
233	    }
234	
235	    public void setCustomerCode(String customerCode) {
236	        this.customerCode = customerCode;
237	    }
238	
239	    /**
240	     * The owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
241	     * digits of the {@link FiscalYear fiscal year} the {@code registrationDate} falls in
242	     * (the fiscal year starts on 1 July), e.g. {@code "FY26"}. Derived on read from the
243	     * owner's registration date; {@code null} until it has been assigned.
244	     */
245	    @Transient
246	    public String getFiscalYear() {
247	        if (this.registrationDate == null) {
248	            return null;
249	        }
250	        return FiscalYear.labelOf(this.registrationDate);
251	    }
252	
253	    /**
254	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
255	     * {@code YY} is the last two digits of the {@link FiscalYear fiscal year} the
256	     * {@code registrationDate} falls in (the fiscal year starts on 1 July), e.g.
257	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
258	     * both the customer code and registration date have been assigned.
259	     */
260	    @Transient
261	    public String getMembershipNumber() {
262	        if (this.customerCode == null || this.registrationDate == null) {
263	            return null;
264	        }
265	        return String.format("%s-M%02d", this.customerCode, FiscalYear.startYearOf(this.registrationDate) % 100);
266	    }
267	
268	    /**
269	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
270	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
271	     * assigned.
272	     */
273	    @Transient
274	    public Integer getCheckDigit() {
275	        if (this.customerCode == null) {
276	            return null;
277	        }
278	        return Luhn.checkDigit(this.customerCode);
279	    }
280	
281	    /**
282	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
283	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
284	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
285	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
286	     * segment of the owner's {@link #getCustomerCode() customer code}.
287	     */
288	    @Transient
289	    public String getRegion() {
290	        return RegionPostcodeTable.regionOf(this.postcode)
291	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
292	    }
293	
294	    /**
295	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
296	     * segment (everything before the first {@code '-'}) of the owner's
297	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
298	     * {@link #getRegion() region} until a customer code has been assigned.
299	     */
300	    @Transient
301	    public String getLocality() {
302	        if (this.customerCode == null) {
303	            return getRegion();
304	        }
305	        int dash = this.customerCode.indexOf('-');
306	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
307	    }
308	
309	    /**
310	     * The owner's IANA timezone name, derived on read from the owner's
311	     * {@link #getLocality() locality} via the fixed {@link RegionTimezoneTable}, e.g.
312	     * {@code "Australia/Sydney"} for {@code NSW}. {@code null} when the locality has no
313	     * timezone in the table.
314	     */
315	    @Transient
316	    public String getTimezone() {
317	        return RegionTimezoneTable.timezoneOf(getLocality());
318	    }
319	
320	    /**
321	     * The owner's preferred contact channel, derived on read from the owner's own
322	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
323	     * {@code "PHONE"}.
324	     */
325	    @Transient
326	    public String getContactPreference() {
327	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
328	    }
329	
330	    /**
331	     * The owner's identity key: the single value used to detect duplicate owners on
332	     * create. It joins the owner's (already normalized) telephone, email and household id
333	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
334	     * household id contributing an empty segment. Two owners are duplicates only when
335	     * their whole identity keys are equal.
336	     */
337	    @Transient
338	    public String getIdentityKey() {
339	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
340	    }
341	
342	    private static String orEmpty(String value) {
343	        return value == null ? "" : value;
344	    }
345	
346	    public String getHouseholdId() {
347	        return this.householdId;
348	    }
349	
350	    public void setHouseholdId(String householdId) {
351	        this.householdId = householdId;
352	    }
353	
354	    public Integer getNamesakeCount() {
355	        return this.namesakeCount;
356	    }
357	
358	    public void setNamesakeCount(Integer namesakeCount) {
359	        this.namesakeCount = namesakeCount;
360	    }
361	
362	    public Integer getHouseholdSize() {
363	        return this.householdSize;
364	    }
365	
366	    public void setHouseholdSize(Integer householdSize) {
367	        this.householdSize = householdSize;
368	    }
369	
370	    /**
371	     * The owner's membership points, assigned on create by tallying the owner's standing:
372	     * points for having an email address, for having no namesakes, for a large household and
373	     * for tenure (see {@code MembershipLevelAssigner}). The points determine the owner's
374	     * {@link #getMembershipLevel() membership level}.
375	     */
376	    public Integer getMembershipPoints() {
377	        return this.membershipPoints;
378	    }
379	
380	    public void setMembershipPoints(Integer membershipPoints) {
381	        this.membershipPoints = membershipPoints;
